import{_ as t,o as i,c as s,ag as a}from"./chunks/framework.7He2WLS4.js";const g=JSON.parse('{"title":"Mobile Device Certificate Setup","description":"","frontmatter":{},"headers":[],"relativePath":"certificate/mobile.md","filePath":"certificate/mobile.md","lastUpdated":1772297611000}'),o={name:"certificate/mobile.md"};function n(r,e,l,c,p,d){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="mobile-device-certificate-setup" tabindex="-1">Mobile Device Certificate Setup <a class="header-anchor" href="#mobile-device-certificate-setup" aria-label="Permalink to &quot;Mobile Device Certificate Setup&quot;">​</a></h1><p>This guide covers setting up the NectoProxy CA certificate on iOS and Android devices so you can inspect HTTPS traffic from mobile apps and browsers.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before setting up a mobile device, ensure:</p><ol><li><p><strong>NectoProxy is running</strong> on your computer. NectoProxy binds to all interfaces by default, so mobile devices on the same network can connect:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div></li><li><p><strong>Your mobile device and computer are on the same Wi-Fi network.</strong></p></li><li><p><strong>Know your computer&#39;s local IP address</strong> (e.g., <code>192.168.1.100</code>). Find it with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> getifaddr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> en0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $1}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipconfig</span></span></code></pre></div></li></ol><h2 id="ios-setup" tabindex="-1">iOS Setup <a class="header-anchor" href="#ios-setup" aria-label="Permalink to &quot;iOS Setup&quot;">​</a></h2><h3 id="step-1-configure-the-wi-fi-proxy" tabindex="-1">Step 1: Configure the Wi-Fi Proxy <a class="header-anchor" href="#step-1-configure-the-wi-fi-proxy" aria-label="Permalink to &quot;Step 1: Configure the Wi-Fi Proxy&quot;">​</a></h3><ol><li>Open <strong>Settings</strong> on your iPhone or iPad.</li><li>Tap <strong>Wi-Fi</strong>.</li><li>Tap the <strong>(i)</strong> icon next to your connected Wi-Fi network.</li><li>Scroll down and tap <strong>Configure Proxy</strong>.</li><li>Select <strong>Manual</strong>.</li><li>Enter: <ul><li><strong>Server</strong>: Your computer&#39;s local IP address (e.g., <code>192.168.1.100</code>)</li><li><strong>Port</strong>: <code>8888</code></li><li><strong>Authentication</strong>: Leave off</li></ul></li><li>Tap <strong>Save</strong>.</li></ol><h3 id="step-2-download-the-ca-certificate" tabindex="-1">Step 2: Download the CA Certificate <a class="header-anchor" href="#step-2-download-the-ca-certificate" aria-label="Permalink to &quot;Step 2: Download the CA Certificate&quot;">​</a></h3><ol><li>Open <strong>Safari</strong> (you must use Safari -- other browsers will not trigger the certificate install flow).</li><li>Navigate to: <code>http://&lt;your-computer-ip&gt;:8889/cert</code><ul><li>For example: <code>http://192.168.1.100:8889/cert</code></li><li>This URL is served by the NectoProxy Web UI and provides the CA certificate for download.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Alternative: Transfer the Certificate File</p><p>If the download URL does not work, you can transfer the <code>ca.pem</code> file to your iOS device via AirDrop, email, or iCloud Drive, then open it from the Files app.</p></div><ol start="3"><li>A prompt will appear: &quot;This website is trying to download a configuration profile. Do you want to allow this?&quot;</li><li>Tap <strong>Allow</strong>.</li></ol><h3 id="step-3-install-the-certificate-profile" tabindex="-1">Step 3: Install the Certificate Profile <a class="header-anchor" href="#step-3-install-the-certificate-profile" aria-label="Permalink to &quot;Step 3: Install the Certificate Profile&quot;">​</a></h3><ol><li>Open <strong>Settings</strong>.</li><li>A new option appears near the top: <strong>Profile Downloaded</strong>. Tap it. <ul><li>If you do not see this, go to Settings &gt; General &gt; VPN &amp; Device Management (or &quot;Profiles&quot; on older iOS versions).</li></ul></li><li>Tap <strong>Install</strong> in the top-right corner.</li><li>Enter your device passcode if prompted.</li><li>Tap <strong>Install</strong> again on the warning screen.</li><li>Tap <strong>Done</strong>.</li></ol><h3 id="step-4-trust-the-root-certificate" tabindex="-1">Step 4: Trust the Root Certificate <a class="header-anchor" href="#step-4-trust-the-root-certificate" aria-label="Permalink to &quot;Step 4: Trust the Root Certificate&quot;">​</a></h3><p>Installing the profile is not enough -- you must also explicitly trust the certificate for SSL/TLS:</p><ol><li>Open <strong>Settings &gt; General &gt; About &gt; Certificate Trust Settings</strong>.</li><li>Under &quot;Enable Full Trust for Root Certificates&quot;, find the NectoProxy CA certificate.</li><li>Toggle the switch <strong>on</strong> to enable full trust.</li><li>Tap <strong>Continue</strong> on the warning dialog.</li></ol><div class="warning custom-block"><p class="custom-block-title">Both Steps Required</p><p>On iOS, you must both <strong>install</strong> the profile (Step 3) and <strong>enable trust</strong> (Step 4). Skipping either step will result in certificate warnings.</p></div><h3 id="verify-on-ios" tabindex="-1">Verify on iOS <a class="header-anchor" href="#verify-on-ios" aria-label="Permalink to &quot;Verify on iOS&quot;">​</a></h3><ol><li>Open Safari and navigate to any HTTPS website.</li><li>The page should load without certificate warnings.</li><li>Check the NectoProxy Web UI on your computer to see the captured traffic.</li></ol><h3 id="remove-on-ios" tabindex="-1">Remove on iOS <a class="header-anchor" href="#remove-on-ios" aria-label="Permalink to &quot;Remove on iOS&quot;">​</a></h3><ol><li>Go to Settings &gt; General &gt; VPN &amp; Device Management (or Profiles).</li><li>Tap the NectoProxy profile.</li><li>Tap <strong>Remove Profile</strong> and confirm.</li><li>Remember to also reset your proxy settings: Settings &gt; Wi-Fi &gt; (i) &gt; Configure Proxy &gt; Off.</li></ol><hr><h2 id="android-setup" tabindex="-1">Android Setup <a class="header-anchor" href="#android-setup" aria-label="Permalink to &quot;Android Setup&quot;">​</a></h2><h3 id="step-1-configure-the-wi-fi-proxy-1" tabindex="-1">Step 1: Configure the Wi-Fi Proxy <a class="header-anchor" href="#step-1-configure-the-wi-fi-proxy-1" aria-label="Permalink to &quot;Step 1: Configure the Wi-Fi Proxy&quot;">​</a></h3><ol><li>Open <strong>Settings</strong> on your Android device.</li><li>Tap <strong>Network &amp; Internet</strong> (or <strong>Wi-Fi</strong>, depending on your device).</li><li>Long-press your connected Wi-Fi network and select <strong>Modify network</strong> (or tap the gear icon).</li><li>Tap <strong>Advanced options</strong> to expand additional settings.</li><li>Under <strong>Proxy</strong>, select <strong>Manual</strong>.</li><li>Enter: <ul><li><strong>Proxy hostname</strong>: Your computer&#39;s local IP address (e.g., <code>192.168.1.100</code>)</li><li><strong>Proxy port</strong>: <code>8888</code></li><li><strong>Bypass proxy for</strong>: Leave empty</li></ul></li><li>Tap <strong>Save</strong>.</li></ol><h3 id="step-2-download-the-ca-certificate-1" tabindex="-1">Step 2: Download the CA Certificate <a class="header-anchor" href="#step-2-download-the-ca-certificate-1" aria-label="Permalink to &quot;Step 2: Download the CA Certificate&quot;">​</a></h3><ol><li>Open your browser (Chrome works well).</li><li>Navigate to: <code>http://&lt;your-computer-ip&gt;:8889/cert</code><ul><li>For example: <code>http://192.168.1.100:8889/cert</code></li></ul></li><li>The certificate file (<code>ca.pem</code> or <code>ca.crt</code>) will download to your device.</li></ol><div class="tip custom-block"><p class="custom-block-title">Alternative: Transfer the File</p><p>You can also transfer the <code>ca.pem</code> file to your device via USB, email, or cloud storage. Rename it to <code>nectoproxy-ca.crt</code> before transferring, as Android recognizes the <code>.crt</code> extension more reliably.</p></div><h3 id="step-3-install-the-certificate" tabindex="-1">Step 3: Install the Certificate <a class="header-anchor" href="#step-3-install-the-certificate" aria-label="Permalink to &quot;Step 3: Install the Certificate&quot;">​</a></h3><p>The exact steps vary by Android version and manufacturer:</p><p><strong>Android 11 and later:</strong></p><ol><li>Open <strong>Settings &gt; Security &gt; More security settings &gt; Encryption &amp; credentials</strong> (or Settings &gt; Security &gt; Advanced &gt; Encryption &amp; credentials).</li><li>Tap <strong>Install a certificate</strong> (or <strong>Install from storage</strong>).</li><li>Select <strong>CA certificate</strong>.</li><li>You will see a warning about CA certificates. Tap <strong>Install anyway</strong>.</li><li>Select the downloaded certificate file.</li><li>The certificate is installed.</li></ol><p><strong>Android 7-10:</strong></p><ol><li>Open <strong>Settings &gt; Security &gt; Install from storage</strong> (or Settings &gt; Security &amp; lock screen &gt; Encryption &amp; credentials &gt; Install from storage).</li><li>Navigate to the downloaded certificate file and select it.</li><li>Give it a name (e.g., &quot;NectoProxy CA&quot;).</li><li>Under <strong>Credential use</strong>, select <strong>VPN and apps</strong> or <strong>Wi-Fi</strong>.</li><li>Tap <strong>OK</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Android 7+ User Certificate Limitations</p><p>Starting with Android 7 (Nougat), Google changed how user-installed CA certificates work:</p><ul><li><strong>User-installed CA certificates are only trusted by the browser</strong>, not by apps by default.</li><li>Apps targeting API level 24+ (Android 7+) do <strong>not</strong> trust user-added CAs unless the app&#39;s <code>network_security_config.xml</code> explicitly allows it.</li><li>This means you can inspect browser traffic without issues, but <strong>native app traffic may not be interceptible</strong> unless the app opts in.</li></ul><p><strong>Workarounds for inspecting app traffic on Android 7+:</strong></p><ol><li><p><strong>Debug builds</strong>: If you control the app, add a network security configuration that trusts user CAs:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- res/xml/network_security_config.xml --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">network-security-config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">debug-overrides</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">trust-anchors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">certificates</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">trust-anchors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">debug-overrides</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">network-security-config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div></li><li><p><strong>Rooted device</strong>: Install the certificate as a system CA in <code>/system/etc/security/cacerts/</code>.</p></li><li><p><strong>Android emulator</strong>: Use an emulator with a writable system partition and install the certificate at the system level.</p></li></ol></div><h3 id="verify-on-android" tabindex="-1">Verify on Android <a class="header-anchor" href="#verify-on-android" aria-label="Permalink to &quot;Verify on Android&quot;">​</a></h3><ol><li>Open Chrome and navigate to any HTTPS website.</li><li>The page should load without certificate warnings.</li><li>Check the NectoProxy Web UI on your computer to see the captured traffic.</li></ol><h3 id="remove-on-android" tabindex="-1">Remove on Android <a class="header-anchor" href="#remove-on-android" aria-label="Permalink to &quot;Remove on Android&quot;">​</a></h3><ol><li>Go to Settings &gt; Security &gt; Encryption &amp; credentials &gt; Trusted credentials.</li><li>Tap the <strong>User</strong> tab.</li><li>Find the NectoProxy CA certificate and tap it.</li><li>Tap <strong>Remove</strong> (or <strong>Disable</strong>).</li><li>Remember to also reset your proxy settings: Wi-Fi network settings &gt; Proxy &gt; None.</li></ol><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="no-traffic-appearing-in-nectoproxy" tabindex="-1">No Traffic Appearing in NectoProxy <a class="header-anchor" href="#no-traffic-appearing-in-nectoproxy" aria-label="Permalink to &quot;No Traffic Appearing in NectoProxy&quot;">​</a></h3><ul><li><strong>Verify NectoProxy is listening on all interfaces</strong>: Make sure you did not start NectoProxy with <code>--host 127.0.0.1</code>, which restricts access to localhost only. The default (<code>0.0.0.0</code>) allows LAN connections.</li><li><strong>Same network</strong>: Confirm your mobile device and computer are on the same Wi-Fi network.</li><li><strong>Firewall</strong>: Check that your computer&#39;s firewall allows incoming connections on port 8888 and 8889.</li><li><strong>Correct IP</strong>: Double-check the computer&#39;s IP address. It may change if you reconnect to Wi-Fi.</li></ul><h3 id="certificate-download-url-not-working" tabindex="-1">Certificate Download URL Not Working <a class="header-anchor" href="#certificate-download-url-not-working" aria-label="Permalink to &quot;Certificate Download URL Not Working&quot;">​</a></h3><p>If <code>http://&lt;ip&gt;:8889/cert</code> does not work:</p><ul><li>Try accessing the NectoProxy Web UI directly: <code>http://&lt;ip&gt;:8889</code>. If this does not load, there is a network connectivity issue.</li><li>Manually transfer the certificate file from <code>~/.nectoproxy/certs/ca.pem</code> to your mobile device.</li></ul><h3 id="ios-profile-downloaded-not-appearing" tabindex="-1">iOS: &quot;Profile Downloaded&quot; Not Appearing <a class="header-anchor" href="#ios-profile-downloaded-not-appearing" aria-label="Permalink to &quot;iOS: &quot;Profile Downloaded&quot; Not Appearing&quot;">​</a></h3><ul><li>Make sure you opened the certificate URL in <strong>Safari</strong>, not Chrome or another browser.</li><li>Go to Settings &gt; General &gt; VPN &amp; Device Management to check if the profile is listed there.</li><li>Try restarting the Settings app.</li></ul><h3 id="android-app-traffic-not-captured" tabindex="-1">Android: App Traffic Not Captured <a class="header-anchor" href="#android-app-traffic-not-captured" aria-label="Permalink to &quot;Android: App Traffic Not Captured&quot;">​</a></h3><p>This is expected behavior on Android 7+ due to network security configuration changes. See the <a href="#android-setup">Android 7+ User Certificate Limitations</a> section above for workarounds.</p><details class="details custom-block"><summary>Testing with Android Emulator</summary><p>For the most reliable Android debugging experience, use an Android emulator with Google APIs (not Google Play) image. These images have a writable system partition, allowing you to install the certificate at the system level:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Push the certificate to the emulator&#39;s system CA store</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remount</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.nectoproxy/certs/ca.pem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /system/etc/security/cacerts/nectoproxy.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 644</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /system/etc/security/cacerts/nectoproxy.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><p>After reboot, the certificate will be a system-trusted CA, and all apps will trust it regardless of their network security configuration.</p></details>`,52)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
